"use client"

import * as React from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import { Eye, EyeOff, Mail, Lock, ArrowRight, Loader2 } from "lucide-react"
import { useForm } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"
import * as z from "zod"
import { useTranslations } from "next-intl"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Checkbox } from "@/components/ui/checkbox"
import { Separator } from "@/components/ui/separator"
import { GoogleIcon, GitHubIcon, AppleIcon } from "@/components/icons/social-icons"
import { useToast } from "@/components/ui/toast"
import { authApi } from "@/lib/auth"
import { getErrorMessage } from "@/lib/api-axios"

export default function LoginPage() {
  const t = useTranslations()
  const router = useRouter()
  const { showToast } = useToast()
  const [showPassword, setShowPassword] = React.useState(false)
  const [isLoading, setIsLoading] = React.useState(false)
  const [socialLoading, setSocialLoading] = React.useState<string | null>(null)

  const loginSchema = z.object({
    email: z.string().email(t("auth.validation.emailInvalid")),
    password: z.string().min(8, t("auth.validation.passwordMinLength")),
    rememberMe: z.boolean().optional(),
  })

  type LoginFormData = z.infer<typeof loginSchema>

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<LoginFormData>({
    resolver: zodResolver(loginSchema),
    defaultValues: {
      email: "",
      password: "",
      rememberMe: false,
    },
  })

  const onSubmit = async (data: LoginFormData) => {
    setIsLoading(true)
    try {
      const response = await authApi.login({
        email: data.email,
        password: data.password,
      })
      
      // Store token and user info in localStorage
      localStorage.setItem("auth_token", response.token)
      localStorage.setItem("auth_user", JSON.stringify({
        email: response.email,
        firstName: response.firstName,
        lastName: response.lastName,
        role: response.role,
      }))
      
      showToast('success', t('auth.login.success'))
      router.push("/dashboard")
    } catch (error) {
      const message = getErrorMessage(error)
      showToast('error', message)
    } finally {
      setIsLoading(false)
    }
  }

  const handleSocialLogin = async (provider: string) => {
    setSocialLoading(provider)
    try {
      // Social login requires OAuth setup - show coming soon message for now
      showToast('info', `${provider} login coming soon!`)
    } catch (error) {
      console.error(`${provider} login error:`, error)
    } finally {
      setSocialLoading(null)
    }
  }

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="space-y-2 text-center">
        <h1 className="text-3xl font-bold tracking-tight bg-gradient-to-r from-slate-900 to-slate-700 bg-clip-text text-transparent">
          {t("auth.login.title")}
        </h1>
        <p className="text-slate-500">
          {t("auth.login.description")}
        </p>
      </div>

      {/* Social login buttons */}
      <div className="grid grid-cols-3 gap-3">
        <Button
          variant="outline"
          className="h-12"
          onClick={() => handleSocialLogin("google")}
          disabled={!!socialLoading}
        >
          {socialLoading === "google" ? (
            <Loader2 className="w-5 h-5 animate-spin" />
          ) : (
            <GoogleIcon className="w-5 h-5" />
          )}
        </Button>
        <Button
          variant="outline"
          className="h-12"
          onClick={() => handleSocialLogin("github")}
          disabled={!!socialLoading}
        >
          {socialLoading === "github" ? (
            <Loader2 className="w-5 h-5 animate-spin" />
          ) : (
            <GitHubIcon className="w-5 h-5" />
          )}
        </Button>
        <Button
          variant="outline"
          className="h-12"
          onClick={() => handleSocialLogin("apple")}
          disabled={!!socialLoading}
        >
          {socialLoading === "apple" ? (
            <Loader2 className="w-5 h-5 animate-spin" />
          ) : (
            <AppleIcon className="w-5 h-5" />
          )}
        </Button>
      </div>

      {/* Divider */}
      <div className="relative">
        <div className="absolute inset-0 flex items-center">
          <Separator />
        </div>
        <div className="relative flex justify-center text-xs uppercase">
          <span className="bg-slate-50/50 px-3 text-slate-500">
            {t("common.orContinueWithEmail")}
          </span>
        </div>
      </div>

      {/* Login form */}
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
        {/* Email field */}
        <div className="space-y-2">
          <Label htmlFor="email">{t("auth.login.email")}</Label>
          <div className="relative">
            <Mail className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <Input
              id="email"
              type="email"
              placeholder={t("auth.login.emailPlaceholder")}
              className="pl-11"
              {...register("email")}
            />
          </div>
          {errors.email && (
            <p className="text-sm text-red-500">{errors.email.message}</p>
          )}
        </div>

        {/* Password field */}
        <div className="space-y-2">
          <div className="flex items-center justify-between ltr-flex">
            <Label htmlFor="password">{t("auth.login.password")}</Label>
            <Link
              href="/forgot-password"
              className="text-sm font-medium text-sky-600 hover:text-sky-700 transition-colors"
            >
              {t("common.forgotPassword")}
            </Link>
          </div>
          <div className="relative">
            <Lock className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <Input
              id="password"
              type={showPassword ? "text" : "password"}
              placeholder={t("auth.login.passwordPlaceholder")}
              className="pl-11 pr-11"
              {...register("password")}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 transition-colors"
            >
              {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
            </button>
          </div>
          {errors.password && (
            <p className="text-sm text-red-500">{errors.password.message}</p>
          )}
        </div>

        {/* Remember me */}
        <div className="flex items-center gap-2 ltr-flex">
          <Checkbox id="rememberMe" {...register("rememberMe")} />
          <Label htmlFor="rememberMe" className="text-sm font-normal cursor-pointer">
            {t("common.rememberMe")}
          </Label>
        </div>

        {/* Submit button */}
        <Button type="submit" className="w-full h-12" disabled={isLoading}>
          {isLoading ? (
            <>
              <Loader2 className="w-5 h-5 animate-spin" />
              <span>{t("auth.login.signingIn")}</span>
            </>
          ) : (
            <>
              <span>{t("common.signIn")}</span>
              <ArrowRight className="w-5 h-5" />
            </>
          )}
        </Button>
      </form>

      {/* Sign up link */}
      <p className="text-center text-sm text-slate-500">
        {t("common.dontHaveAccount")}{" "}
        <Link
          href="/register"
          className="font-semibold text-sky-600 hover:text-sky-700 transition-colors"
        >
          {t("common.createAccount")}
        </Link>
      </p>
    </div>
  )
}
